  let y=136; const sec=t=>{ font('PublicSansXB','normal',7.4,GOLDDK); doc.text(t.toUpperCase(),L,y,{charSpace:1.1}); y+=6; doc.setDrawColor(...GOLD); doc.setLineWidth(1); doc.line(L,y,R,y); y+=14; }; const row=(k,v,b)=>{ font('PublicSans',b?'bold':'normal',b?10.5:9.5,INK); doc.text(k,L,y); doc.text(v,R,y,{align:'right'}); y+=14; };
