  if(POS.tickets==null){ posLoad().then(()=>render()); m.innerHTML=head('Point of sale','Loading…'); return; }
  const OL=P.outlets.filter(x=>!POS.dept||outletDept(x)===POS.dept); const OLS=OL.length?OL:P.outlets; if(!OLS.some(x=>x.id===POS.outlet)) POS.outlet=OLS[0].id; const o=outletOf(POS.outlet);
