  const prods=P.products.filter(x=>x.outlet===o.id&&x.active!==false), cats=[...new Set(prods.map(x=>x.cat||''))].sort((a,c)=>a.localeCompare(c)); if(POS.cat&&!cats.includes(POS.cat)) POS.cat='';
