function productDrawer(x){ const P=posSettings();
  openDrawer({kicker:'Point of sale',title:x?x.name:'New product',body:field('Name','pN',x?x.name:'')+pair(field('Outlet','pO',x?x.outlet:(POS.outlet||P.outlets[0].id),{type:'select',options:P.outlets.map(o=>[o.id,o.name])}),field('Category','pC',x?x.cat:'',{ph:'Drinks · Sandwiches · Balls'}))+pair(field('Price $ (before tax)','pP',x?x.price:'',{type:'number'}),field('SKU','pS',x?x.sku||'':''))+
      pair(field('Sales tax','pT',x&&x.taxable!=null?(x.taxable?'yes':'no'):'',{type:'select',options:[['','As the outlet'],['yes','Yes'],['no','No']]}),field('Service charge','pV',x&&x.svc!=null?(x.svc?'yes':'no'):'',{type:'select',options:[['','As the outlet'],['yes','Yes'],['no','No']]}))+
      `<div id="pFnb">${(o=>o&&o.kind==='fnb'?field('Fires to','pRt',x&&x.route||'',{type:'select',options:[['','Nowhere (rung and served here — bar drinks)']].concat(outletSetup(o).expos.map(e=>[e.id,e.name])),hint:'The prep station whose expo screen gets this item when the check is sent.'})+(outletSetup(o).menus.length?`<div class="fld"><span class="lbl">On the menus</span>${o.menus.map(mn=>`<label class="check"><input type="checkbox" data-pm="${mn.id}"${!x||!(x.menus||[]).length||(x.menus||[]).includes(mn.id)?' checked':''}>${esc(mn.name)}</label>`).join('')}</div>`:''):'')(outletOf(x?x.outlet:(POS.outlet||P.outlets[0].id)))}</div>`+
      field('Modifiers','pMods',x?modsText(x.mods):'',{type:'textarea',hint:'One group per line. “Temperature*: Rare, Medium, Well” (* = one must be picked) · “Add-ons+: Bacon +2, Avocado +1.50” (+ = pick several; a price after +/−).'})+field('Course','pCo',x&&x.course||0,{type:'select',options:COURSES.map((c,i)=>[i,c]),hint:'Starters send with the order; mains and dessert hold until the server fires the course.'})+
      `<label class="check"><input type="checkbox" id="pTr"${x&&x.track?' checked':''}>Track stock</label>`+field('Stock on hand','pQ',x?x.stock??'':'',{type:'number'})+`<label class="check"><input type="checkbox" id="pA"${!x||x.active!==false?' checked':''}>On the register</label>`,
    wire:r=>{ r.querySelector('#pO').onchange=()=>{ const o=outletOf(fv('pO')); const h=r.querySelector('#pFnb'); h.innerHTML=o&&o.kind==='fnb'?field('Fires to','pRt',x&&x.route||'',{type:'select',options:[['','Nowhere (rung and served here — bar drinks)']].concat(outletSetup(o).expos.map(e=>[e.id,e.name]))})+(outletSetup(o).menus.length?`<div class="fld"><span class="lbl">On the menus</span>${o.menus.map(mn=>`<label class="check"><input type="checkbox" data-pm="${mn.id}" checked>${esc(mn.name)}</label>`).join('')}</div>`:''):''; }; },
    save:()=>{ const name=fv('pN'), price=fnum('pP'); if(!name){ toast('Name the product'); return false; } const tv=fv('pT'), sv=fv('pV'); const o=outletOf(fv('pO')); const pm=[...$('dBody').querySelectorAll('[data-pm]')]; const menus=pm.length?pm.filter(c=>c.checked).map(c=>c.dataset.pm):[];
      const d={name,outlet:fv('pO'),cat:fv('pC'),price,sku:fv('pS'),taxable:tv===''?null:tv==='yes',svc:sv===''?null:sv==='yes',track:$('pTr').checked,stock:fnum('pQ'),active:$('pA').checked,route:$('pRt')?fv('pRt')||null:(x&&x.route)||null,menus:pm.length&&menus.length===pm.length?[]:menus,mods:parseMods(fv('pMods')),course:+fv('pCo')||0}; if(x) Object.assign(x,d); else P.products.push(Object.assign({id:uid()},d)); persist(); },
    del:x?()=>{ P.products=P.products.filter(y=>y!==x); persist(); }:null}); }
function importProducts(){ const P=posSettings();
  openDrawer({kicker:'Point of sale',title:'Import products',body:field('Outlet','ipO',POS.outlet||P.outlets[0].id,{type:'select',options:P.outlets.map(o=>[o.id,o.name])})+`<div class="fld"><label class="lbl">CSV file</label><input type="file" id="ipF" accept=".csv,text/csv"></div><p class="hint">Columns: <b>name, price</b> and optionally category, sku, stock. A header row is expected. Existing products with the same name in the outlet are updated.</p>`,saveLabel:'Import',
    save:()=>{ const f=$('ipF').files[0]; if(!f){ toast('Choose a file'); return false; } const oid=fv('ipO'); f.text().then(txt=>{ const rows=txt.split(/\r?\n/).filter(l=>l.trim()).map(l=>{ const out=[]; let cur='', q=false; for(const ch of l){ if(ch==='"'){ q=!q; continue; } if(ch===','&&!q){ out.push(cur); cur=''; continue; } cur+=ch; } out.push(cur); return out.map(s=>s.trim()); });
        const H=rows.shift().map(h=>h.toLowerCase()); const ix=k=>H.findIndex(h=>h===k||h.startsWith(k)); const iN=ix('name'), iP=ix('price'), iC=ix('cat'), iS=ix('sku'), iQ=ix('stock'); if(iN<0||iP<0){ toast('Need name and price columns'); return; } let n=0;
        for(const r of rows){ const name=r[iN]; if(!name) continue; const d={name,outlet:oid,cat:iC>=0?r[iC]||'':'',price:n0(String(r[iP]).replace(/[$,]/g,'')),sku:iS>=0?r[iS]||'':'',track:iQ>=0&&r[iQ]!=='',stock:iQ>=0?n0(r[iQ]):0,taxable:null,svc:null,active:true}; const ex=P.products.find(x=>x.outlet===oid&&x.name.toLowerCase()===name.toLowerCase()); if(ex) Object.assign(ex,d); else P.products.push(Object.assign({id:uid()},d)); n++; }
        persist(); toast(`${n} product${n===1?'':'s'} imported`); render(); }); }}); }

/* ============ Restaurants and the shop as the floor sees them: stations, expos, tables, menus, staff PINs ============
   Setup lives in Settings → Food & beverage / Golf shop. A register station is a device with its own link
   (pos.html?s=TOKEN, the hash in pos_stations); an expo station is a kitchen screen (expo.html?k=TOKEN) bound to one of
   the outlet's prep stations (outlet.expos). Servers unlock a station with a PIN (CLUB.pos.staff[].pin = sha256 of
   tenant:pin, checked by pos_pin); a manager's PIN lets someone leave the station. */
const STN={rows:null,loading:false}; CACHE_RESETS.push(()=>{ if(!STN.loading) STN.rows=null; });
const stnKey=()=>'fs_stn_'+((typeof TENANT!=='undefined'&&TENANT)||'local');
function outletSetup(o){ o.tables=o.tables||[]; o.expos=o.expos||[]; o.menus=o.menus||[]; return o; }
async function stnLoad(force){ if(STN.loading) return PENDING; if(STN.rows&&!force) return; STN.loading=true;
  try{ if(!acctCloud()){ try{ STN.rows=JSON.parse(localStorage.getItem(stnKey())||'[]'); }catch(_){ STN.rows=[]; } } else { const r=await tq(sb.from('pos_stations').select('*')); STN.rows=r.error?[]:(r.data||[]); } } finally{ STN.loading=false; } }
function stnLocalWrite(){ if(!acctCloud()){ try{ localStorage.setItem(stnKey(),JSON.stringify(STN.rows||[])); }catch(_){} } }
const pinHash=pin=>sha256hex(((typeof TENANT!=='undefined'&&TENANT)||'local')+':'+String(pin).trim());
const stationURL=(s,token)=>(typeof SITE_BASE!=='undefined'&&SITE_BASE?SITE_BASE:location.origin+'/')+(s.kind==='expo'?'expo.html?k=':s.kind==='clock'?'clock.html?k=':'pos.html?s=')+token;
/* a new station: the token is shown once (like an admin link); the device keeps it */
async function newStation(o,kind,name,expo,dept){ if(!crypto.subtle) throw new Error('This browser cannot create station links (needs https)');
  const token=newToken()+newToken().slice(0,8), hash=await sha256hex(token), row={id:uid(),outlet:o&&o.id||null,kind,expo:expo||null,dept:dept||null,name,key_hash:hash,token,created_at:new Date().toISOString(),revoked_at:null,last_seen:null};
  if(acctCloud()){ const {error}=await sb.from('pos_stations').insert(trow(row)); if(error) throw new Error(/relation|does not exist/i.test(error.message)?'Run pos-stations-setup.sql in Supabase first':error.message); }
  STN.rows=(STN.rows||[]).concat([row]); stnLocalWrite(); return {row,token,url:stationURL(row,token)}; }
/* the link again: the token is kept with the station (staff-only), so Link shows it; a station from before that keeps none,
   so Link mints a new token for it — the device on the old link must open the new one */
async function stationLink(s){ if(s.token) return stationLinkModal({row:s,token:s.token,url:stationURL(s,s.token)});
  if(!confirm(`${s.name} was made before links were kept. Make a new link? Any device still on the old one is signed out and must open the new link.`)) return;
  if(!crypto.subtle){ toast('This browser cannot make station links (needs https)'); return; } const token=newToken()+newToken().slice(0,8), hash=await sha256hex(token), patch={key_hash:hash,token};
  if(acctCloud()){ const {error}=await sb.from('pos_stations').update(patch).eq('id',s.id); if(error){ toast(/column|token/i.test(error.message)?'Run pos-reopen-setup.sql in Supabase first':error.message); return; } } Object.assign(s,patch); stnLocalWrite(); stationLinkModal({row:s,token,url:stationURL(s,token)}); }
async function revokeStation(s){ const patch={revoked_at:new Date().toISOString()}; if(acctCloud()){ const {error}=await sb.from('pos_stations').update(patch).eq('id',s.id); if(error){ toast(error.message); return; } } Object.assign(s,patch); stnLocalWrite(); }
function stationDrawer(o,kind){ outletSetup(o);
  openDrawer({kicker:o.name,title:kind==='expo'?'New expo screen':'New register station',saveLabel:'Create the link',
    body:field('Name','snN','',{ph:kind==='expo'?'Kitchen screen · Grill line':'Bar 1 · Host stand · Shop register 2'})+(kind==='expo'?field('Shows orders for','snE',o.expos[0]?o.expos[0].id:'',{type:'select',options:o.expos.map(e=>[e.id,e.name]),hint:o.expos.length?'':'Add a prep station to the restaurant first (Kitchen, Grill, Bar…).'}):'')+
      `<p class="hint">${kind==='expo'?'Open the link once on the kitchen PC or tablet; it stays on and shows every course fired to that station, newest at the bottom, with a bump button.':'Open the link once on the device at this register; it stays signed in to the station. Servers unlock it with their PIN; a manager’s PIN is needed to leave it.'}</p>`,
    save:async()=>{ const name=fv('snN'); if(!name){ toast('Name it'); return false; } if(kind==='expo'&&!fv('snE')){ toast('Pick the prep station'); return false; }
      try{ const r=await newStation(o,kind,name,kind==='expo'?fv('snE'):null); setTimeout(()=>stationLinkModal(r),50); }catch(e){ toast(e.message); return false; } }}); }
function stationLinkModal(r){ openDrawer({kicker:r.row.name,title:'The station link',saveLabel:'Done',body:`<p>Open this on the device, or scan it. It signs the device in to <b>${esc(r.row.name)}</b> for good; the link stays here behind the station’s Link button. If the device is lost, revoke the station and make a new one.</p><div class="qlink"><input class="inp" id="snUrl" value="${esc(r.url)}" readonly><button class="btn" id="snCopy">Copy</button></div><div id="snQR" style="margin:14px auto 0;width:200px;min-height:200px"></div>`,
    wire:x=>{ x.querySelector('#snCopy').onclick=()=>{ navigator.clipboard&&navigator.clipboard.writeText(r.url); toast('Copied'); }; loadQR().then(()=>{ const q=qrcode(0,'M'); q.addData(r.url); q.make(); x.querySelector('#snQR').innerHTML=q.createSvgTag({cellSize:4,margin:0}); }).catch(()=>{}); },save:()=>{}}); }
/* tables, prep stations, menus, the manager PIN — per outlet */
function tablesDrawer(o){ outletSetup(o); openDrawer({kicker:o.name,title:'Tables',body:field('Tables','tbT',o.tables.join(', '),{type:'textarea',hint:'Numbers, ranges and names, comma-separated: 1-12, Patio 1-6, Bar, Fire pit'}),save:()=>{ o.tables=parseTables(fv('tbT')); persist(); }}); }
function exposDrawer(o){ outletSetup(o); const d=o.expos.map(e=>Object.assign({},e)); if(!d.length) d.push({id:uid(),name:'Kitchen'});
  const rows=()=>d.map((e,i)=>`<div class="mr" style="grid-template-columns:minmax(0,1fr) 28px"><input class="inp" data-ei="${i}" value="${esc(e.name)}" placeholder="Kitchen · Grill · Pantry · Bar"><button class="ib" data-edel="${i}" type="button" aria-label="Remove">${I.x}</button></div>`).join('');
  openDrawer({kicker:o.name,title:'Prep stations (expo)',body:`<div class="fld"><div style="display:flex;justify-content:space-between;align-items:center"><span class="lbl">Where orders fire to</span><button class="btn sm" id="exAdd" type="button">${I.plus}Station</button></div><div class="mini"><div id="exRows">${rows()}</div></div><p class="hint">Each menu item names the station it fires to (Kitchen, Grill, Pantry…); drinks rung at the bar fire nowhere. An expo screen in the kitchen follows one station.</p></div>`,
    wire:r=>{ const bind=()=>{ r.querySelectorAll('[data-ei]').forEach(e=>e.oninput=()=>d[+e.dataset.ei].name=e.value); r.querySelectorAll('[data-edel]').forEach(b=>b.onclick=()=>{ d.splice(+b.dataset.edel,1); r.querySelector('#exRows').innerHTML=rows(); bind(); }); }; bind(); r.querySelector('#exAdd').onclick=()=>{ d.push({id:uid(),name:''}); r.querySelector('#exRows').innerHTML=rows(); bind(); }; },
    save:()=>{ o.expos=d.filter(e=>e.name.trim()).map(e=>({id:e.id,name:e.name.trim()})); persist(); }}); }
function menusDrawer(o){ outletSetup(o); const d=o.menus.map(m=>Object.assign({},m)); if(!d.length) d.push({id:uid(),name:'All day',active:true});
  const rows=()=>d.map((m,i)=>`<div class="mr" style="grid-template-columns:minmax(0,1fr) 90px 28px"><input class="inp" data-mi="${i}" value="${esc(m.name)}" placeholder="Lunch · Dinner · Bar · Locker room"><label class="check" style="font-size:12.5px"><input type="checkbox" data-ma="${i}"${m.active!==false?' checked':''}>On now</label><button class="ib" data-mdel="${i}" type="button" aria-label="Remove">${I.x}</button></div>`).join('');
  openDrawer({kicker:o.name,title:'Menus',body:`<div class="fld"><div style="display:flex;justify-content:space-between;align-items:center"><span class="lbl">Menus</span><button class="btn sm" id="mnAdd" type="button">${I.plus}Menu</button></div><div class="mini"><div id="mnRows">${rows()}</div></div><p class="hint">A product can be on several menus; the register shows the menus that are on. Switch Lunch off and Dinner on at five.</p></div>`,
    wire:r=>{ const bind=()=>{ r.querySelectorAll('[data-mi]').forEach(e=>e.oninput=()=>d[+e.dataset.mi].name=e.value); r.querySelectorAll('[data-ma]').forEach(e=>e.onchange=()=>d[+e.dataset.ma].active=e.checked); r.querySelectorAll('[data-mdel]').forEach(b=>b.onclick=()=>{ d.splice(+b.dataset.mdel,1); r.querySelector('#mnRows').innerHTML=rows(); bind(); }); }; bind(); r.querySelector('#mnAdd').onclick=()=>{ d.push({id:uid(),name:'',active:true}); r.querySelector('#mnRows').innerHTML=rows(); bind(); }; },
    save:()=>{ o.menus=d.filter(m=>m.name.trim()).map(m=>({id:m.id,name:m.name.trim(),active:m.active!==false})); persist(); }}); }
/* staff and their PINs live club-wide in CLUB.staff (staff.js); the restaurants see the food & beverage people */
const posStaff=()=>clubStaff();
/* the Settings → Food & beverage / Golf shop tabs */
function svcCard(){ const b=acctSettings(); return `<div class="card"><div class="cardhead"><div><h2 class="h2">Service charge · ${n0(b.svc.rate)}%</h2><span class="muted">Mandatory on every food &amp; beverage check${n0(b.tax.rate)?', taxed where the item is taxed':''}. Tips are not asked for in the app: the printed slip carries the tip, total and signature lines, and the server closes the check out with what was written. Tips over ${tipFlag().pct}% or ${fmt2(tipFlag().amount)} are flagged at the daily close-out.</span></div><div class="actions"><button class="btn sm" id="fbSvc">${I.edit}Change</button></div></div></div>`; }
function svcDrawer(){ const b=acctSettings(), f=tipFlag(); openDrawer({title:'Service charge & tips',body:field('Service charge %','svR',b.svc.rate,{type:'number',hint:'On every food & beverage check (items marked for it). 18% unless the club says otherwise; it is taxed where tax applies.'})+'<p class="lbl" style="margin-top:8px">Tips over the limit are flagged at the close-out and need a second look</p>'+pair(field('Over this % of the payment','svP',f.pct,{type:'number'}),field('Or over this amount','svA',f.amount,{type:'number'})),save:()=>{ b.svc.rate=Math.max(0,fnum('svR')); f.pct=Math.max(0,fnum('svP')); f.amount=Math.max(0,fnum('svA')); persist(); }}); }
function fnbSetupHTML(kind){ const P=posSettings(), outs=P.outlets.filter(o=>o.kind===kind), S=STN.rows||[], staff=kind==='fnb'?staffOf('fnb'):clubStaff().filter(x=>!x.depts.length||x.depts.some(d=>P.outlets.some(o=>o.kind==='proshop'&&outletDept(o)===d)));
  const outletCard=o=>{ outletSetup(o); const st=S.filter(s=>s.outlet===o.id&&!s.revoked_at), regs=st.filter(s=>s.kind!=='expo'), exps=st.filter(s=>s.kind==='expo'), np=P.products.filter(p=>p.outlet===o.id).length;
    return (kind==='fnb'?svcCard():'')+`<div class="card"><div class="cardhead"><div><h2 class="h2">${esc(o.name)}</h2><span class="muted">${np} products · bills as ${esc((itemOf(o.item)||{}).name||o.item)}</span></div><div class="actions"><button class="btn sm" data-oe="${o.id}">${I.edit}Edit</button><button class="btn sm" data-op="${o.id}">Menu items</button><button class="btn sm" data-ol="${o.id}">${I.lib}Library</button></div></div>
      <div class="fnbgrid">
        <div class="fnbcol"><b>Register stations</b>${regs.length?regs.map(s=>`<div class="stn"><span>${esc(s.name)}<small>${s.last_seen?'seen '+new Date(s.last_seen).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'never opened'}</small></span><span style="display:flex;gap:2px"><button class="ib" data-sl="${s.id}" aria-label="Link" title="Show the link">${I.lib}</button><button class="ib" data-sr="${s.id}" aria-label="Revoke">${I.x}</button></span></div>`).join(''):'<span class="muted">None yet — each device at a register gets its own link.</span>'}<button class="btn sm" data-ns="${o.id}">${I.plus}Register station</button></div>
        ${kind==='fnb'?`<div class="fnbcol"><b>Prep stations &amp; expo screens</b>${o.expos.length?`<div class="chips">${o.expos.map(e=>`<span class="chip">${esc(e.name)}</span>`).join('')}</div>`:'<span class="muted">No prep stations — Kitchen, Grill, Bar…</span>'}${exps.map(s=>`<div class="stn"><span>${esc(s.name)}<small>screen · ${esc((o.expos.find(e=>e.id===s.expo)||{}).name||'?')}${s.last_seen?' · seen '+new Date(s.last_seen).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):''}</small></span><button class="ib" data-sr="${s.id}" aria-label="Revoke">${I.x}</button></div>`).join('')}<div class="actions"><button class="btn sm" data-ex="${o.id}">Prep stations</button><button class="btn sm" data-ne="${o.id}">${I.plus}Expo screen</button></div></div>
        <div class="fnbcol"><b>Tables</b><span class="muted">${o.tables.length?o.tables.length+' tables: '+esc(o.tables.slice(0,8).join(', '))+(o.tables.length>8?'…':''):'None yet — bar tabs still work by name'}</span><div class="actions"><button class="btn sm" data-tb="${o.id}">Tables</button></div></div>
        <div class="fnbcol"><b>Menus</b><span class="muted">${o.menus.length?o.menus.map(m=>esc(m.name)+(m.active===false?' (off)':'')).join(' · '):'One menu, everything on it'}</span><div class="actions"><button class="btn sm" data-mn="${o.id}">Menus</button></div></div>`:''}
      </div></div>`; };
  return `${outs.map(outletCard).join('')||`<div class="card"><div class="empty"><b>No ${kind==='fnb'?'restaurants':'shop outlets'} yet</b><span>${kind==='fnb'?'Add the Creekside Grill, the Nines Bistro, the men’s locker room — each is a restaurant with its own stations, tables and menus.':'Add the golf shop; each register in it gets a station link.'}</span></div></div>`}
    <div class="actions" style="margin:-6px 0 10px"><button class="btn pri" id="fbNewO">${I.plus}${kind==='fnb'?'Restaurant':'Shop outlet'}</button></div>
    <div class="card" style="overflow:hidden"><div class="cardhead"><div><h2 class="h2">Staff &amp; PINs</h2><span class="muted">${kind==='fnb'?'Servers, bartenders and managers':'The shop staff'} unlock a station with their PIN; managers can leave it and void checks. The schedule and the time clock are on the Staff page.</span></div><div class="actions"><button class="btn sm" data-go2="staff">Staff &amp; schedule</button><button class="btn sm" id="fbNewS">${I.plus}Person</button></div></div>
      ${staff.length?`<div class="t"><div class="tr th" style="grid-template-columns:minmax(140px,1.4fr) 110px minmax(120px,1.4fr) 70px 44px"><span>Name</span><span>Role</span><span>Works at</span><span>PIN</span><span></span></div>${staff.map(x=>`<div class="tr${x.active===false?' void':''}" style="grid-template-columns:minmax(140px,1.4fr) 110px minmax(120px,1.4fr) 70px 44px"><div class="cell2"><b>${esc(x.name)}</b></div><span>${esc(x.role||'server')}</span><span class="muted">${(x.outlets||[]).length?x.outlets.map(id=>esc((outletOf(id)||{}).name||'')).join(', '):'everywhere'}</span><span>${x.pin?'set':'<span class="neg">none</span>'}</span><span class="actions"><button class="ib" data-se="${x.id}" aria-label="Edit">${I.edit}</button></span></div>`).join('')}</div>`:'<div class="empty"><b>Nobody yet</b><span>Add each server and bartender with a PIN, and at least one manager.</span></div>'}</div>`; }
function wireFnbSetup(m,kind){ const P=posSettings(); const sv=$('fbSvc'); if(sv) sv.onclick=svcDrawer;
  $('fbNewO').onclick=()=>outletDrawer(null,kind); $('fbNewS').onclick=()=>staffMemberDrawer(null,kind==='fnb'?'fnb':'golf'); m.querySelectorAll('[data-go2]').forEach(x=>x.onclick=()=>{ ST.dept=kind==='fnb'?'fnb':''; go(x.dataset.go2); });
  m.querySelectorAll('[data-oe]').forEach(x=>x.onclick=()=>outletDrawer(outletOf(x.dataset.oe))); m.querySelectorAll('[data-op]').forEach(x=>x.onclick=()=>{ POS.outlet=x.dataset.op; go('possetup'); }); m.querySelectorAll('[data-ol]').forEach(x=>x.onclick=()=>posLibraryDrawer(x.dataset.ol));
  m.querySelectorAll('[data-ns]').forEach(x=>x.onclick=()=>stationDrawer(outletOf(x.dataset.ns),'register')); m.querySelectorAll('[data-ne]').forEach(x=>x.onclick=()=>stationDrawer(outletOf(x.dataset.ne),'expo'));
  m.querySelectorAll('[data-sl]').forEach(x=>x.onclick=()=>stationLink((STN.rows||[]).find(y=>y.id===x.dataset.sl)));
  m.querySelectorAll('[data-sr]').forEach(x=>x.onclick=async()=>{ const s=(STN.rows||[]).find(y=>y.id===x.dataset.sr); if(!confirm(`Revoke ${s.name}? The device will be signed out the next time it talks to the station.`)) return; await revokeStation(s); render(); });
  m.querySelectorAll('[data-ex]').forEach(x=>x.onclick=()=>exposDrawer(outletOf(x.dataset.ex))); m.querySelectorAll('[data-tb]').forEach(x=>x.onclick=()=>tablesDrawer(outletOf(x.dataset.tb))); m.querySelectorAll('[data-mn]').forEach(x=>x.onclick=()=>menusDrawer(outletOf(x.dataset.mn)));
  m.querySelectorAll('[data-se]').forEach(x=>x.onclick=()=>staffMemberDrawer(staffById(x.dataset.se),kind==='fnb'?'fnb':'')); }

/* ============ check numbers, signed slips and the daily close-out ============
   The owner, Oct 2026: paper slips stay. Every check carries a number (MMDD-NNNC, a check digit on the end) printed large on the
   slip with a QR behind it; at the end of the day the signed slips are scanned, the software reads each image (QR, else OCR against
   the day's numbers — matchSlipText in poscore), stores it against the payment and the member's charge, and the day is closed and
   locked (pos_days): nothing on it is reopened, voided or re-tipped without a manager's PIN. pos-closeout-setup.sql. */
const CO={outlet:'',day:'',log:[],tray:[],busy:false,reader:null,local:{},worker:null};
const DAYS={rows:null,loading:false}; CACHE_RESETS.push(()=>{ if(!DAYS.loading) DAYS.rows=null; });
const daysKey=()=>`fs_days_${(typeof TENANT!=='undefined'&&TENANT)||'local'}`;
async function daysLoad(force){ if(DAYS.loading) return PENDING; if(DAYS.rows&&!force) return; DAYS.loading=true;
  try{ if(!acctCloud()){ try{ DAYS.rows=JSON.parse(localStorage.getItem(daysKey())||'[]'); }catch(_){ DAYS.rows=[]; } }
    else { const r=await tq(sb.from('pos_days').select('*').gte('day',isoPlus(todayISO(),-120))); DAYS.rows=r.error?[]:(r.data||[]); } }
  finally{ DAYS.loading=false; } }
function daysLocalWrite(){ if(!acctCloud()){ try{ localStorage.setItem(daysKey(),JSON.stringify(DAYS.rows||[])); }catch(_){} } }
const ticketDay=t=>t.day||String(t.closed_at||t.created_at||'').slice(0,10);
const dayRowOf=(outlet,day)=>(DAYS.rows||[]).find(d=>d.outlet===outlet&&d.day===day)||null;
const dayClosed=t=>!!dayRowOf(t.outlet,ticketDay(t));
/* a manager's PIN in the hub: the same PIN that unlocks a register (clubStaff, role manager) */
async function managerPIN(why){ const pin=prompt(`${why||'A manager’s PIN is needed.'}\nManager PIN:`); if(pin==null||!pin.trim()) return null; if(!crypto.subtle){ toast('PINs need https'); return null; }
  const h=await pinHash(pin); const who=clubStaff().find(x=>x.active!==false&&x.role==='manager'&&x.pin===h); if(!who) toast('Not a manager’s PIN'); return who||null; }
async function dayLockOK(t,what){ if(!dayClosed(t)) return true; return !!(await managerPIN(`${dateTxt(ticketDay(t))} is closed. To ${what||'change this check'} anyway, a manager’s PIN is needed.`)); }
/* check numbers: the counter lives in the database (pos_next_check); local mode counts in localStorage */
async function nextCheckNo(outletId,day){ day=day||todayISO();
  if(acctCloud()){ const {data,error}=await sb.rpc('pos_next_check',{p_tenant:TENANT,p_outlet:outletId,p_day:day}); if(!error&&data) return data; }
  const k=`fs_ckno_${outletId}_${day}`; let n=0; try{ n=parseInt(localStorage.getItem(k)||'0')||0; }catch(_){} n++; try{ localStorage.setItem(k,String(n)); }catch(_){} return checkNoFor(day,n); }
/* the payments that want a signed slip on a ticket: account and card. A hub-register ticket from before split payments carries one implied payment */
function slipPays(t){ const P=(t.payments&&t.payments.length)?t.payments:(t.paid&&t.paid!=='cash'?[{id:'t:'+t.id,method:t.paid,amount:n0(t.total),tip:n0(t.tip),acct_item:t.acct_item,slip:t.slip||null,implied:true}]:[]); return P.filter(p=>p.method==='account'||p.method==='card'); }
const slipPath=(t,p)=>`${(typeof TENANT!=='undefined'&&TENANT)||'local'}/${t.id}/${String(p.id).replace(/^t:/,'')}.jpg`;
async function slipURL(path){ if(!path) return null; if(CO.local[path]) return CO.local[path]; if(!acctCloud()||!sb.storage) return null; try{ const {data,error}=await sb.storage.from('slips').createSignedUrl(path,600); if(error) throw error; return data.signedUrl; }catch(e){ toast('Couldn’t open the slip: '+(e.message||'')); return null; } }
async function showSlip(path,title){ const url=await slipURL(path); if(!url){ toast('The signed slip is not available'); return; } const ov=document.createElement('div'); ov.className='rf-show'; ov.style.cssText='display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;background:rgba(15,42,56,.92);padding:20px';
  ov.innerHTML=`<b style="color:#fff;font-family:var(--serif);font-size:22px">${esc(title||'Signed slip')}</b><img src="${url}" alt="signed slip" style="max-height:80vh;max-width:min(92vw,520px);background:#fff;border-radius:8px;box-shadow:0 10px 40px rgba(0,0,0,.4)"><div style="display:flex;gap:8px"><a class="btn" href="${url}" target="_blank" rel="noopener" style="color:var(--navy)">Open full size</a><button class="btn" id="slX">Close</button></div>`;
  document.body.appendChild(ov); ov.querySelector('#slX').onclick=()=>ov.remove(); ov.onclick=e=>{ if(e.target===ov) ov.remove(); }; }
/* storing a scan against a payment: the file in the bucket, the path on the payment and on the member's charge */
async function attachSlip(t,p,blob,dataURL){ const path=slipPath(t,p);
  if(acctCloud()){ if(!sb.storage){ toast('Storage is not available'); return false; } const up=await sb.storage.from('slips').upload(path,blob,{upsert:true,contentType:'image/jpeg'}); if(up.error){ toast('Couldn’t store the slip: '+up.error.message); return false; } }
  else CO.local[path]=dataURL;
  const pays=(t.payments&&t.payments.length)?t.payments.map(x=>x.id===p.id?Object.assign({},x,{slip:path}):x):[Object.assign({},p,{slip:path})]; delete pays[0].implied;
  if(acctCloud()){ const {error}=await sb.from('pos_tickets').update({payments:pays}).eq('id',t.id); if(error){ toast('Couldn’t save: '+error.message); return false; } } t.payments=pays; posLocalWrite();
  if(p.acct_item){ await acctLoad(true); const it=(ACCT.items||[]).find(i=>i.id===p.acct_item); if(it){ if(acctCloud()){ await sb.from('acct_items').update({slip:path}).eq('id',it.id); } it.slip=path; if(!acctCloud()) acctLocalWrite(); } }
  return true; }
/* reading an image: the QR first (jsQR), else OCR (tesseract.js) against the day's check numbers; tests inject CO.reader */
function loadScript(src){ return new Promise((ok,bad)=>{ const s=document.createElement('script'); s.src=src; s.onload=ok; s.onerror=()=>bad(new Error('Couldn’t load '+src.split('/').pop())); document.head.appendChild(s); }); }
async function readSlipImage(canvas){ if(CO.reader) return CO.reader(canvas); const out={qr:null,text:''};
  try{ if(!window.jsQR) await loadScript('https://cdnjs.cloudflare.com/ajax/libs/jsQR/1.4.0/jsQR.min.js'); const g=canvas.getContext('2d'), d=g.getImageData(0,0,canvas.width,canvas.height); const c=window.jsQR(d.data,d.width,d.height); if(c&&c.data) out.qr=c.data; }catch(_){}
  if(out.qr) return out;
  try{ if(!window.Tesseract) await loadScript('https://cdnjs.cloudflare.com/ajax/libs/tesseract.js/5.1.1/tesseract.min.js'); if(!CO.worker) CO.worker=await window.Tesseract.createWorker('eng'); const r=await CO.worker.recognize(canvas); out.text=(r&&r.data&&r.data.text)||''; }catch(e){ out.err=e.message; }
  return out; }
async function fileToCanvases(file){ const out=[]; const fit=(w,h)=>{ const s=Math.min(1,1800/Math.max(w,h)); return [Math.round(w*s),Math.round(h*s)]; };
  if(/pdf$/i.test(file.type)||/\.pdf$/i.test(file.name)){ await loadPdfJs(); const pdf=await window.pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise; for(let i=1;i<=pdf.numPages;i++){ const pg=await pdf.getPage(i); const v0=pg.getViewport({scale:1}); const scale=Math.min(2.2,1600/Math.max(v0.width,v0.height)); const v=pg.getViewport({scale}); const c=document.createElement('canvas'); c.width=Math.round(v.width); c.height=Math.round(v.height); const g=c.getContext('2d'); g.fillStyle='#fff'; g.fillRect(0,0,c.width,c.height); await pg.render({canvasContext:g,viewport:v}).promise; out.push(c); } return out; }
  const url=URL.createObjectURL(file); try{ const im=await new Promise((ok,bad)=>{ const i=new Image(); i.onload=()=>ok(i); i.onerror=()=>bad(new Error('Not an image')); i.src=url; }); const [w,h]=fit(im.naturalWidth,im.naturalHeight); const c=document.createElement('canvas'); c.width=w; c.height=h; const g=c.getContext('2d'); g.fillStyle='#fff'; g.fillRect(0,0,w,h); g.drawImage(im,0,0,w,h); out.push(c); } finally{ URL.revokeObjectURL(url); } return out; }
const canvasBlob=c=>new Promise(ok=>c.toBlob(b=>ok(b),'image/jpeg',0.82));
function coTickets(){ return (POS.tickets||[]).filter(t=>t.outlet===CO.outlet&&ticketDay(t)===CO.day); }
function coExpected(){ const out=[]; for(const t of coTickets()){ if(t.status!=='closed'&&t.status!=='slip') continue; for(const p of slipPays(t)) out.push({t,p}); } return out; }
/* the scans, one by one: match → attach; no match or more than one payment to choose from → the tray */
async function coProcess(files){ if(CO.busy) return; CO.busy=true; const nos={}; coTickets().forEach(t=>{ if(t.check_no) nos[t.check_no]=t; });
  try{ for(const f of files){ let cs=[]; try{ cs=await fileToCanvases(f); }catch(e){ CO.log.push({ok:false,msg:`${f.name}: ${e.message}`}); continue; }
      for(const c of cs){ const r=await readSlipImage(c); const blob=await canvasBlob(c), dataURL=c.toDataURL('image/jpeg',0.6); let t=null, p=null, how='';
        const q=/^fs:([^:]+):([^:]*)$/.exec(r.qr||''); if(q){ t=coTickets().find(x=>x.id===q[1])||null; if(t){ const P=slipPays(t); p=P.find(x=>String(x.id).replace(/^t:/,'')===q[2])||(P.length===1?P[0]:null); how='QR'; } }
        if(!t&&r.text){ const m=matchSlipText(r.text,Object.keys(nos)); if(m){ t=nos[m.no]; how=m.how==='exact'?'check number':'check number (read with a correction)'; const P=slipPays(t); p=P.length===1?P[0]:null; } }
        if(t&&p){ const ok=await attachSlip(t,p,blob,dataURL); CO.log.push({ok,msg:`${t.check_no||''} · ${coWho(t,p)} · ${fmt2(n0(p.amount))} — matched by ${how}`}); }
        else { CO.tray.push({id:uid(),blob,dataURL,t,text:(r.text||'').trim().slice(0,80),err:r.err}); CO.log.push({ok:false,msg:t?`${t.check_no} has ${slipPays(t).length} payments — pick which one in the tray`:`No check number read — in the tray${r.err?' ('+r.err+')':''}`}); } } }
  } finally{ CO.busy=false; render(); } }
const coWho=(t,p)=>{ const m=p.member_id||t.member_id; const who=m?memberName(personById(m)||{})||'Member':t.guest||(t.table_no?'Table '+t.table_no:'Walk-in'); return `${p.method==='account'?'account · ':'card · '}${who}${p.label?' · '+p.label:''}`; };
async function coAttachFromTray(item,key){ const [tid,pid]=String(key).split('|'); const t=coTickets().find(x=>x.id===tid); if(!t) return; const p=slipPays(t).find(x=>String(x.id)===pid); if(!p) return;
  if(await attachSlip(t,p,item.blob,item.dataURL)){ CO.tray=CO.tray.filter(x=>x.id!==item.id); CO.log.push({ok:true,msg:`${t.check_no||''} · ${coWho(t,p)} — attached by hand`}); render(); } }
function tipFlag(){ const P=posSettings(); P.tipFlag=Object.assign({pct:30,amount:50},P.tipFlag||{}); return P.tipFlag; }
const tipFlagged=(p)=>{ const f=tipFlag(), tip=n0(p.tip), base=n0(p.amount)-tip; return tip>0&&(tip>f.amount||(base>0&&tip>base*f.pct/100)); };
function vCloseout(m){ if(!posOn()){ go('dash'); return; }
  if(POS.tickets==null||DAYS.rows==null||(typeof ACCT!=='undefined'&&acctOn()&&ACCT.items==null)){ Promise.all([posLoad(),daysLoad(),acctOn()?acctLoad():null]).then(()=>render()); m.innerHTML=head('Daily close-out','Loading…'); return; }
  const outs=posSettings().outlets; if(!CO.outlet||!outs.some(o=>o.id===CO.outlet)) CO.outlet=(outs.find(o=>o.kind==='fnb')||outs[0]||{}).id||''; if(!CO.day) CO.day=todayISO();
  const o=outletOf(CO.outlet)||{name:'—'}, T=coTickets(), closed=T.filter(t=>t.status==='closed'||t.status==='slip'), open=T.filter(t=>t.status==='open'), out=T.filter(t=>t.status==='slip'), voids=T.filter(t=>t.status==='void');
  const exp=coExpected(), scanned=exp.filter(x=>x.p.slip), missing=exp.filter(x=>!x.p.slip), S=shiftStats(T), day=dayRowOf(CO.outlet,CO.day), f=tipFlag();
  const srv={}; closed.forEach(t=>{ const k=t.server||'—'; srv[k]=srv[k]||{n:0,sales:0,tips:0,flag:0}; srv[k].n++; srv[k].sales+=n0(t.total)-n0(t.tip); for(const p of ((t.payments&&t.payments.length)?t.payments:[{method:t.paid,amount:n0(t.total),tip:n0(t.tip)}])){ srv[k].tips+=n0(p.tip); if(tipFlagged(p)) srv[k].flag++; } });
  const flagged=[]; closed.forEach(t=>slipPays(t).forEach(p=>{ if(tipFlagged(p)) flagged.push({t,p}); }));
  const pendTips=exp.filter(x=>x.p.slip&&x.p.tip==null);
  const who=t=>t.member_id?memberName(personById(t.member_id)||{})||'Member':t.guest||(t.table_no?'Table '+t.table_no:'Walk-in');
  m.innerHTML=`<div class="crumb"><button id="coBack">Point of sale</button><span class="muted">/</span><span class="muted">Daily close-out</span></div>`+head('Daily close-out',`${esc(o.name)} · ${dateTxt(CO.day)}${day?` · <b>closed ${new Date(day.closed_at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})} by ${esc(day.closed_by||'')}</b>`:''}`,btn('Close-out PDF','coPdf','',I.down)+(day?btn('Reopen the day','coReopen','danger'):btn('Close the day','coClose','pri')))+`
    <div class="toolbar"><div class="seg">${outs.map(x=>`<button class="${CO.outlet===x.id?'on':''}" data-co="${x.id}">${esc(x.name)}</button>`).join('')}</div><input class="inp" type="date" id="coDay" value="${CO.day}" style="height:38px;width:170px"></div>
    <div class="grid g4">${kpi('Checks',String(closed.length),`${fmt2(S.sales)} net sales · ${voids.length} void${voids.length===1?'':'s'}`)}${kpi('Signed slips',`${scanned.length} / ${exp.length}`,missing.length?`${missing.length} not scanned yet`:exp.length?'every slip accounted for':'no account or card payments',missing.length?'neg':'')}${kpi('Still to deal with',String(open.length+out.length),`${open.length} open · ${out.length} out for a tip`,open.length+out.length?'neg':'')}${kpi('Tips',fmt2(S.tips),flagged.length?`${flagged.length} over the limit (${f.pct}% or ${fmt2(f.amount)})`:`none over ${f.pct}% or ${fmt2(f.amount)}`,flagged.length?'neg':'')}</div>
    <div class="card lg" style="overflow:hidden"><div class="cardhead"><div><h2 class="h2">Scan the signed slips</h2><span class="muted">Drop the scanner's PDF or photos here. Each page is read for its check number (or the QR) and tied to the ticket and the member's charge.</span></div><div class="actions"><input type="file" id="coFiles" multiple accept="image/*,application/pdf" hidden><button class="btn pri" id="coPick">${I.plus}Add scans</button></div></div>
      <div id="coDrop" style="margin:0 22px 16px;border:2px dashed var(--line);border-radius:12px;padding:22px;text-align:center;color:var(--muted)">${CO.busy?'Reading…':'Drop files here — a PDF of the whole stack, or one photo per slip'}</div>
      ${CO.log.length?`<div style="padding:0 22px 14px;display:grid;gap:4px">${CO.log.slice(-40).map(l=>`<div style="font-size:13px"><span class="chip ${l.ok?'ok':'warn'}" style="height:18px;font-size:11px">${l.ok?'matched':'look'}</span> ${esc(l.msg)}</div>`).join('')}</div>`:''}
      ${CO.tray.length?`<div style="padding:0 22px 16px"><b>In the tray — pick the ticket for each</b><div class="grid g3" style="margin-top:8px">${CO.tray.map(x=>`<div class="setupcard"><img src="${x.dataURL}" alt="" style="max-height:160px;max-width:100%;object-fit:contain;border:1px solid var(--line);border-radius:8px;background:#fff"><small class="muted">${esc(x.text||'nothing readable')}</small><select class="inp" data-trs="${x.id}"><option value="">— which payment —</option>${exp.map(e=>`<option value="${e.t.id}|${e.p.id}" ${x.t&&x.t.id===e.t.id?'selected':''}>${esc(e.t.check_no||'')} · ${esc(coWho(e.t,e.p))} · ${fmt2(n0(e.p.amount))}${e.p.slip?' · has a slip':''}</option>`).join('')}</select><div class="actions"><button class="btn sm pri" data-tra="${x.id}">Attach</button><button class="btn sm" data-trx="${x.id}">Discard</button></div></div>`).join('')}</div></div>`:''}
      ${missing.length?`<div style="padding:0 22px 18px"><b>Not scanned yet</b>${missing.map(e=>`<div class="lr" style="padding:6px 0"><div class="cell2"><span class="ln">${esc(e.t.check_no||'no number')} · ${esc(coWho(e.t,e.p))}</span><span class="ls">${esc(e.t.server||'')}${e.t.table_no?' · table '+esc(e.t.table_no):''}</span></div><b class="lnet">${fmt2(n0(e.p.amount))}</b></div>`).join('')}</div>`:''}</div>
    ${pendTips.length?`<div class="card lg" style="overflow:hidden"><div class="cardhead"><div><h2 class="h2">Tips to enter from the scans</h2><span class="muted">These slips are scanned but the tip was never entered. Read it off the image.</span></div></div><div class="grid g3" style="padding:0 22px 16px">${pendTips.map(e=>`<div class="setupcard"><b>${esc(e.t.check_no||'')} · ${esc(coWho(e.t,e.p))}</b><span class="muted">${fmt2(n0(e.p.amount))}</span><button class="btn sm" data-sv="${e.p.slip}">View the slip</button><div style="display:flex;gap:6px;align-items:center"><input class="inp" data-tipin="${e.t.id}|${e.p.id}" inputmode="decimal" placeholder="Tip" style="width:100px"><button class="btn sm pri" data-tipok="${e.t.id}|${e.p.id}">Save</button></div></div>`).join('')}</div></div>`:''}
    ${open.length+out.length?`<div class="card lg" style="overflow:hidden"><div class="cardhead"><div><h2 class="h2">Still to deal with</h2><span class="muted">The day cannot close with a check open or a slip out for its tip.</span></div><div class="actions"><button class="btn sm" id="coTix">Tickets</button></div></div>${open.concat(out).map(t=>`<div class="lr"><div class="cell2"><span class="ln">${esc(t.check_no||'')} · ${esc(who(t))}${t.status==='slip'?' <span class="chip" style="height:18px;font-size:11px;background:#FFF4D6">slip out</span>':' <span class="chip warn" style="height:18px;font-size:11px">open</span>'}</span><span class="ls">${esc(t.server||'')}${t.table_no?' · table '+esc(t.table_no):''} · ${new Date(t.created_at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</span></div><b class="lnet">${fmt2(n0(t.total))}</b></div>`).join('')}</div>`:''}
    <div class="grid g2"><div class="card lg" style="overflow:hidden"><div class="cardhead"><div><h2 class="h2">Tips by server</h2><span class="muted">Account and card tips owed on the paycheck</span></div></div>${Object.entries(srv).sort((a,b)=>b[1].sales-a[1].sales).map(([n,s])=>`<div class="lr"><div class="cell2"><span class="ln">${esc(n)}${s.flag?` <span class="chip warn" style="height:18px;font-size:11px">${s.flag} over the limit</span>`:''}</span><span class="ls">${s.n} check${s.n===1?'':'s'} · ${fmt2(s.sales)} sales</span></div><b class="lnet">${fmt2(s.tips)}</b></div>`).join('')||'<div class="empty"><span>No checks closed yet.</span></div>'}
        ${flagged.length?`<div style="padding:8px 22px 16px"><b>Over the limit</b>${flagged.map(e=>`<div class="lr" style="padding:6px 0"><div class="cell2"><span class="ln">${esc(e.t.check_no||'')} · ${esc(coWho(e.t,e.p))}</span><span class="ls">${esc(e.t.server||'')} · ${fmt2(n0(e.p.amount)-n0(e.p.tip))} + <b>${fmt2(n0(e.p.tip))} tip</b>${e.p.slip?' · slip scanned':' · <b>no slip scanned</b>'}</span></div>${e.p.slip?`<button class="btn sm" data-sv="${e.p.slip}">Slip</button>`:''}</div>`).join('')}</div>`:''}</div>
      <div class="card lg" style="overflow:hidden"><div class="cardhead"><div><h2 class="h2">Cash drawer</h2><span class="muted">Cash taken against what is in the drawer</span></div></div><div style="padding:0 22px 16px;display:grid;gap:8px">
        <div class="lr" style="padding:6px 0"><span class="ln">Cash sales</span><b class="lnet">${fmt2(S.by.cash)}</b></div><div class="lr" style="padding:6px 0"><span class="ln">Counted in the drawer</span><input class="inp" id="coCash" inputmode="decimal" value="${day?n0(day.cash_counted)||'':''}" ${day?'disabled':''} style="width:140px;text-align:right"></div><div class="lr" style="padding:6px 0"><span class="ln">Over / short</span><b class="lnet" id="coDiff">${day&&day.cash_counted!=null?fmt2(n0(day.cash_counted)-S.by.cash):'—'}</b></div>
        ${voids.length?`<b style="margin-top:8px">Voids</b>${voids.map(t=>`<div class="lr" style="padding:6px 0"><div class="cell2"><span class="ln">${esc(t.check_no||'')} · ${esc(who(t))}</span><span class="ls">${esc(t.server||'')} · ${esc(t.void_reason||'')}</span></div><b class="lnet">${fmt2(n0(t.total))}</b></div>`).join('')}`:''}
        <label class="lbl" style="margin-top:8px">Notes for the office</label><textarea class="inp" id="coNotes" rows="3" ${day?'disabled':''}>${esc(day?day.notes||'':CO.notes||'')}</textarea>
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><input class="inp" id="coTo" placeholder="E-mail the close-out to…" value="${esc(posSettings().closeoutTo||'')}" style="flex:1;min-width:200px"><button class="btn" id="coMail">${I.mail||''}Send</button></div></div></div></div>`;
  $('coBack').onclick=()=>go('pos'); m.querySelectorAll('[data-co]').forEach(x=>x.onclick=()=>{ CO.outlet=x.dataset.co; CO.tray=[]; CO.log=[]; render(); }); $('coDay').onchange=()=>{ CO.day=$('coDay').value||todayISO(); CO.tray=[]; CO.log=[]; render(); };
  const ct=$('coTix'); if(ct) ct.onclick=()=>{ POS.day=CO.day; POS.rep=CO.outlet; go('postickets'); };
  $('coPick').onclick=()=>$('coFiles').click(); $('coFiles').onchange=()=>{ const fs=[...$('coFiles').files]; if(fs.length) coProcess(fs); }; const dz=$('coDrop'); dz.ondragover=e=>{ e.preventDefault(); dz.style.borderColor='var(--gold)'; }; dz.ondragleave=()=>{ dz.style.borderColor=''; }; dz.ondrop=e=>{ e.preventDefault(); dz.style.borderColor=''; const fs=[...(e.dataTransfer.files||[])]; if(fs.length) coProcess(fs); };
  m.querySelectorAll('[data-tra]').forEach(b=>b.onclick=()=>{ const x=CO.tray.find(y=>y.id===b.dataset.tra); const sel=m.querySelector(`[data-trs="${b.dataset.tra}"]`); if(!sel.value){ toast('Pick the payment'); return; } coAttachFromTray(x,sel.value); }); m.querySelectorAll('[data-trx]').forEach(b=>b.onclick=()=>{ CO.tray=CO.tray.filter(y=>y.id!==b.dataset.trx); render(); });
  m.querySelectorAll('[data-sv]').forEach(b=>b.onclick=()=>showSlip(b.dataset.sv));
  m.querySelectorAll('[data-tipok]').forEach(b=>b.onclick=async()=>{ const [tid,pid]=b.dataset.tipok.split('|'); const t=coTickets().find(x=>x.id===tid); const v=m.querySelector(`[data-tipin="${b.dataset.tipok}"]`).value; const tip=Math.max(0,Math.round((parseFloat(v)||0)*100)/100); const p=slipPays(t).find(x=>String(x.id)===pid); if(tipFlagged(Object.assign({},p,{tip,amount:n0(p.amount)+tip}))&&!confirm(`${fmt2(tip)} on ${fmt2(n0(p.amount))} is over the limit — is that what is written?`)) return; if(await settleTicket(t,[{id:pid,tip}],{partial:true})){ toast('Tip entered'); render(); } });
  const cc=$('coCash'); if(cc) cc.oninput=()=>{ $('coDiff').textContent=cc.value===''?'—':fmt2(n0(cc.value)-S.by.cash); }; const cn=$('coNotes'); if(cn) cn.oninput=()=>{ CO.notes=cn.value; };
  $('coPdf').onclick=()=>closeoutPDF({o,T,closed,open,out,voids,exp,scanned,missing,S,srv,flagged,day,cash:$('coCash')?$('coCash').value:'',notes:$('coNotes')?$('coNotes').value:''});
  $('coMail').onclick=async()=>{ const to=$('coTo').value.trim(); if(!to){ toast('Who should it go to?'); return; } posSettings().closeoutTo=to; persist(); const doc=await closeoutPDF({o,T,closed,open,out,voids,exp,scanned,missing,S,srv,flagged,day,cash:$('coCash').value,notes:$('coNotes').value,returnDoc:true}); if(!doc) return; const b64=doc.output('datauristring').split(',')[1];
    const r=await sendMail({to,subject:`${o.name} close-out — ${dateTxt(CO.day)}`,text:`The close-out for ${o.name}, ${dateTxt(CO.day)}, is attached.`,html:mailHTML({title:'Daily close-out',paragraphs:[`The close-out for <b>${esc(o.name)}</b>, ${dateTxt(CO.day)}, is attached.`,`${closed.length} checks · ${fmt2(S.sales)} net sales · ${scanned.length} of ${exp.length} signed slips scanned · tips ${fmt2(S.tips)}.`]}),attachments:[{filename:`closeout-${CO.outlet}-${CO.day}.pdf`,content:b64}]}); toast(r&&r.error?'Not sent: '+r.error:'Sent'); };
  const cl=$('coClose'); if(cl) cl.onclick=()=>closeDay({open,out,missing,S,exp,scanned,closed}); const ro=$('coReopen'); if(ro) ro.onclick=reopenDay;
}
async function closeDay(x){ if(x.open.length){ toast(`${x.open.length} check${x.open.length===1?' is':'s are'} still open — close or void ${x.open.length===1?'it':'them'} first`); return false; } if(x.out.length){ toast(`${x.out.length} slip${x.out.length===1?' is':'s are'} still out for a tip — enter the tips first`); return false; }
  if(x.missing.length&&!confirm(`${x.missing.length} signed slip${x.missing.length===1?' has':'s have'} not been scanned. Close the day anyway? You can still scan them afterwards.`)) return false;
  const cash=$('coCash')?$('coCash').value:'', row={id:uid(),outlet:CO.outlet,day:CO.day,closed_at:new Date().toISOString(),closed_by:whoAmI(),cash_sales:x.S.by.cash,cash_counted:cash===''?null:Math.round(n0(cash)*100)/100,notes:($('coNotes')?$('coNotes').value:'').slice(0,1000),totals:{n:x.closed.length,sales:x.S.sales,svc:x.S.svc,tax:x.S.tax,tips:x.S.tips,by:x.S.by,slips:{expected:x.exp.length,scanned:x.scanned.length}}};
  if(acctCloud()){ const {error}=await sb.from('pos_days').insert(trow(row)); if(error){ toast('Couldn’t close the day: '+error.message); return false; } } DAYS.rows=(DAYS.rows||[]).concat([row]); daysLocalWrite(); toast(`${dateTxt(CO.day)} closed`); render(); return true; }
async function reopenDay(){ const d=dayRowOf(CO.outlet,CO.day); if(!d) return false; const who=await managerPIN(`Reopen ${dateTxt(CO.day)} for ${(outletOf(CO.outlet)||{}).name||''}? Checks on it can then be changed again.`); if(!who) return false;
  if(acctCloud()){ const {error}=await sb.from('pos_days').delete().eq('id',d.id); if(error){ toast('Couldn’t reopen: '+error.message); return false; } } DAYS.rows=(DAYS.rows||[]).filter(x=>x.id!==d.id); daysLocalWrite(); toast(`Reopened by ${who.name}`); render(); return true; }
/* the close-out sheet: a branded letter page the paper stack is stapled to */
async function closeoutPDF(x){ try{ await loadJsPDF(); }catch(e){ toast(e.message); return null; } const crest=await crestPNG().catch(()=>null), doc=new window.jspdf.jsPDF({unit:'pt',format:'letter'}); bcFonts(doc);
  const NAVY=[15,42,56],GOLD=[199,161,58],GOLDL=[216,183,95],GOLDDK=[126,95,26],IVORY=[251,250,245],INK=[20,34,43],MUTED=[86,98,106],NEG=[181,68,58]; const L=40,R=572,W=612,H=792, font=(f,s,z,c)=>{ doc.setFont(f,s); doc.setFontSize(z); doc.setTextColor(...c); };
  const page=()=>{ doc.setFillColor(...IVORY); doc.rect(0,0,W,H,'F'); }; page(); doc.setFillColor(...GOLD); doc.roundedRect(L,32,R-L,82,8,8,'F'); doc.setFillColor(...NAVY); doc.roundedRect(L,32,R-L,78,8,8,'F'); doc.rect(L,98,R-L,8,'F'); const lw=drawCrest(doc,crest,L+16,42,54), TX=L+16+(lw||45)+15;
  font('PublicSansXB','normal',6.8,GOLDL); doc.text(String(brandName()).toUpperCase(),TX,56,{charSpace:1.2}); font('Cormorant','bold',24,[255,255,255]); doc.text(`Daily close-out — ${x.o.name}`,TX,80); font('PublicSans','normal',8.4,[214,218,220]); doc.text(`${new Date(CO.day+'T12:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'})}${x.day?` · closed ${new Date(x.day.closed_at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})} by ${x.day.closed_by||''}`:' · not yet closed'}`,TX,96);
  let y=136; const need=n=>{ if(y>H-n){ doc.addPage(); page(); y=60; } }; const sec=t=>{ need(60); font('PublicSansXB','normal',7.4,GOLDDK); doc.text(t.toUpperCase(),L,y,{charSpace:1.1}); y+=6; doc.setDrawColor(...GOLD); doc.setLineWidth(1); doc.line(L,y,R,y); y+=14; }; const row=(k,v,b,col)=>{ need(30); font('PublicSans',b?'bold':'normal',b?10.5:9.5,col||INK); doc.text(doc.splitTextToSize(k,R-L-120)[0],L,y); doc.text(v,R,y,{align:'right'}); y+=14; };
  sec('The day'); row('Checks closed',String(x.closed.length)); row('Net sales',fmt2(x.S.sales)); row('Service charge',fmt2(x.S.svc)); row('Sales tax',fmt2(x.S.tax)); row('Tips (account and card)',fmt2(x.S.tips)); row('On member accounts',fmt2(x.S.by.account)); row('Card',fmt2(x.S.by.card)); row('Cash',fmt2(x.S.by.cash)); if(x.voids.length) row(`Voids (${x.voids.length})`,fmt2(x.S.voidAmt)); y+=8;
  sec('Cash drawer'); row('Cash sales',fmt2(x.S.by.cash)); const counted=x.day&&x.day.cash_counted!=null?n0(x.day.cash_counted):(x.cash===''?null:n0(x.cash)); row('Counted',counted==null?'—':fmt2(counted)); if(counted!=null) row('Over / short',fmt2(counted-x.S.by.cash),true,Math.abs(counted-x.S.by.cash)>0.005?NEG:INK); y+=8;
  sec(`Signed slips — ${x.scanned.length} of ${x.exp.length} scanned`); x.exp.slice().sort((a,b)=>String(a.t.check_no||'').localeCompare(String(b.t.check_no||''))).forEach(e=>row(`${e.t.check_no||'—'} · ${coWho(e.t,e.p)} · ${e.t.server||''}${tipFlagged(e.p)?' · OVER THE LIMIT':''}`,`${fmt2(n0(e.p.amount)-n0(e.p.tip))}${n0(e.p.tip)?' + '+fmt2(n0(e.p.tip))+' tip':''} · ${e.p.slip?'scanned':'NOT SCANNED'}`,false,e.p.slip?INK:NEG)); if(!x.exp.length) row('No account or card payments',''); y+=8;
  sec('Tips by server'); Object.entries(x.srv).sort((a,b)=>b[1].tips-a[1].tips).forEach(([n,s])=>row(`${n} · ${s.n} check${s.n===1?'':'s'} · ${fmt2(s.sales)} sales${s.flag?' · '+s.flag+' over the limit':''}`,fmt2(s.tips))); y+=8;
  if(x.voids.length){ sec('Voids'); x.voids.forEach(t=>row(`${t.check_no||'—'} · ${t.server||''} · ${t.void_reason||''}`,fmt2(n0(t.total)))); y+=8; }
  const notes=x.day?x.day.notes:x.notes; if(notes){ sec('Notes'); font('PublicSans','normal',9.5,INK); doc.splitTextToSize(notes,R-L).forEach(l=>{ need(30); doc.text(l,L,y); y+=13; }); }
  y+=24; need(60); font('PublicSans','normal',9,MUTED); doc.text('Closed by ____________________________    Checked by ____________________________',L,y);
  const name=`closeout-${CO.outlet}-${CO.day}.pdf`; if(x.returnDoc) return doc; if(typeof deliverFile==='function') await deliverFile(doc.output('blob'),name,'Close-out'); else doc.save(name); return doc; }
